/**
 * Agent documentation generator
 *
 * Reads every agent JSON file in agents/ and writes a per-agent Markdown page
 * to docs/agents/generated/<agent>.md. Pages are generated from the JSON
 * metadata and from a lightweight static analysis of the referenced JS action
 * files, so they stay in sync when actions change.
 *
 * Usage:
 *   dmtools run agents/js/unit-tests/run_agentDocs.json
 *   node agents/js/agentDocGenerator.js   (Node, not GraalJS)
 */

var fs = require('fs');
var path = require('path');

// Layout-adaptive: 'agents' when invoked from a parent repo (submodule mount),
// '.' when invoked from the dmtools-agents repo root itself. References written
// into generated docs always keep the canonical 'agents/...' prefix so the docs
// are identical no matter which layout generated them.
var PARENT_LAYOUT = fs.existsSync(path.join('agents', 'js', 'agentDocGenerator.js'));
var AGENTS_DIR = PARENT_LAYOUT ? 'agents' : '.';
var DOCS_DIR = path.join(AGENTS_DIR, 'docs', 'agents', 'generated');
var SNAPSHOTS_DIR = path.join(AGENTS_DIR, 'snapshots');

// Resolve a canonical 'agents/...' path to a readable file in either layout.
function resolveReadPath(filePath) {
    if (fs.existsSync(filePath)) return filePath;
    if (!PARENT_LAYOUT && filePath.indexOf('agents/') === 0) {
        var stripped = filePath.substring('agents/'.length);
        if (fs.existsSync(stripped)) return stripped;
    }
    return filePath;
}

// Canonical reference (always 'agents/...-prefixed) for docs output.
function canonicalRef(filePath) {
    // normalize to forward slashes so docs are identical on Windows and Linux
    var normalized = filePath.replace(/\\/g, '/');
    if (!PARENT_LAYOUT && normalized.indexOf('agents/') !== 0) {
        return 'agents/' + normalized;
    }
    return normalized;
}

function ensureDir(dir) {
    try {
        fs.mkdirSync(dir, { recursive: true });
    } catch (e) {
        // ignore
    }
}

function listAgentConfigs() {
    var files = fs.readdirSync(AGENTS_DIR);
    return files.filter(function(f) {
        return f.endsWith('.json') &&
            !f.startsWith('.') &&
            f !== 'sm.json' &&
            f !== 'sm_merge.json' &&
            f !== 'versions.json' && // pack-version registry, not an agent config
            !f.startsWith('run_') &&
            f.indexOf('_lock') === -1;
    }).sort();
}

function readJson(filePath) {
    try {
        return JSON.parse(fs.readFileSync(filePath, 'utf8'));
    } catch (e) {
        console.warn('Could not parse', filePath, ':', e.message);
        return null;
    }
}

function readSource(filePath) {
    try {
        return fs.readFileSync(resolveReadPath(filePath), 'utf8');
    } catch (e) {
        return '';
    }
}

function escapeMd(text) {
    if (!text) return '';
    return String(text).replace(/\|/g, '\\|').replace(/\n/g, '<br>');
}

function unique(arr) {
    var seen = {};
    return arr.filter(function(item) {
        if (seen[item]) return false;
        seen[item] = true;
        return true;
    });
}

function basename(p) {
    return p.replace(/^.*[\\/]/, '');
}

function firstJsDescription(src) {
    var m = src.match(/^\s*\/\*\*\s*\n?\s*\*\s*([^\n]+)/);
    return m ? m[1].replace(/\s+/g, ' ').trim() : '';
}

function statementContext(src, index) {
    var start = src.lastIndexOf('\n', Math.max(0, index - 200));
    var end = src.indexOf('\n', index + 200);
    if (end === -1) end = src.length;
    return src.substring(start + 1, end);
}

function isWriteContext(ctx) {
    return /file_write\s*\(|writeFileSync\s*\(|fs\.writeFile\s*\(/.test(ctx);
}

function isReadContext(ctx) {
    return /file_read\s*\(|readFileSync\s*\(|fs\.readFile\s*\(|jira_attach_file_to_ticket\s*\(/.test(ctx);
}

function normalizeArtifactPath(p) {
    return p.replace(/^\.\//, '').replace(/\/+/g, '/');
}

function withPrefix(prefix, file) {
    return prefix + file;
}

// The file path for one regex match, per the pattern's shape: concat forms
// splice the <KEY> placeholder between the two string literals, prefix
// forms prepend the 'input/<KEY>' stand-in (gh-1085: extracted verbatim —
// both concat branches produce the same splice, kept as documented paths).
function matchedArtifactFile(m, pattern) {
    var file;
    if (pattern.concat) {
        // Insert a placeholder for the variable between the two string literals.
        var left = m[1];
        var right = m[2] || '';
        if (left.slice(-1) === '/' && right.charAt(0) === '/') {
            file = left + '<KEY>' + right;
        } else {
            file = left + '<KEY>' + right;
        }
    } else {
        file = m[1];
    }
    if (pattern.prefix) file = withPrefix(pattern.prefix, file);
    return file;
}

function collectArtifacts(src, phase) {
    var reads = [];
    var writes = [];

    function add(list, p) {
        p = normalizeArtifactPath(p);
        if (p === 'input/' || p === 'outputs/') return;
        list.push(p);
    }

    // Targeted patterns for file path arguments. Each pattern is run globally.
    // dir: 'read' or 'write'; prefix: optional string prepended to capture group 1.
    // concat: combine capture groups 1 and 2 (e.g. 'input/' + key + '/file.md').
    var patterns = [
        // file_write/read first positional argument
        { re: /file_write\s*\(\s*['"`]([^'"`\n]*(?:input\/|outputs\/)[^'"`\n]*)['"`]/g, dir: 'write' },
        { re: /file_read\s*\(\s*['"`]([^'"`\n]*(?:input\/|outputs\/)[^'"`\n]*)['"`]/g, dir: 'read' },
        // file_write({ path: '...' })
        { re: /file_write\s*\(\s*\{[^}]*path\s*:\s*['"`]([^'"`\n]*(?:input\/|outputs\/)[^'"`\n]*)['"`]/g, dir: 'write' },
        // file_write('input/' + key + '/file')
        { re: /file_write\s*\(\s*['"`]([^'"`\n]*(?:input\/|outputs\/)[^'"`\n]*)['"`]\s*\+\s*[A-Za-z0-9_$.]+\s*\+\s*['"`]([^'"`\n]*)['"`]/g, dir: 'write', concat: true },
        // file_write({ path: 'input/' + key + '/file' })
        { re: /file_write\s*\(\s*\{[^}]*path\s*:\s*['"`]([^'"`\n]*(?:input\/|outputs\/)[^'"`\n]*)['"`]\s*\+\s*[A-Za-z0-9_$.]+\s*\+\s*['"`]([^'"`\n]*)['"`]/g, dir: 'write', concat: true },
        // file_write(inputFolder + '/file')
        { re: /file_write\s*\(\s*(?:inputFolder|inputFolderPath|folder)\s*\+\s*['"`]([^'"`\n]+)['"`]/g, dir: 'write', prefix: 'input/<KEY>' },
        // file_read(inputFolder + '/file')
        { re: /file_read\s*\(\s*(?:inputFolder|inputFolderPath|folder)\s*\+\s*['"`]([^'"`\n]+)['"`]/g, dir: 'read', prefix: 'input/<KEY>' },
        // fs.writeFileSync(path.join(inputFolder, 'file'))
        { re: /writeFileSync\s*\(\s*path\.join\s*\(\s*(?:inputFolder|inputFolderPath|folder)\s*,\s*['"`]([^'"`\n]+)['"`]/g, dir: 'write', prefix: 'input/<KEY>' },
        // fs.readFileSync(path.join(inputFolder, 'file'))
        { re: /readFileSync\s*\(\s*path\.join\s*\(\s*(?:inputFolder|inputFolderPath|folder)\s*,\s*['"`]([^'"`\n]+)['"`]/g, dir: 'read', prefix: 'input/<KEY>' },
        // file_write(path.join(inputFolder, 'file'))
        { re: /file_write\s*\(\s*path\.join\s*\(\s*(?:inputFolder|inputFolderPath|folder)\s*,\s*['"`]([^'"`\n]+)['"`]/g, dir: 'write', prefix: 'input/<KEY>' },
        // file_read(path.join(inputFolder, 'file'))
        { re: /file_read\s*\(\s*path\.join\s*\(\s*(?:inputFolder|inputFolderPath|folder)\s*,\s*['"`]([^'"`\n]+)['"`]/g, dir: 'read', prefix: 'input/<KEY>' },
        // jira_attach_file_to_ticket({ filePath: '...' })
        { re: /jira_attach_file_to_ticket\s*\(\s*\{[^}]*filePath\s*:\s*['"`]([^'"`\n]*(?:input\/|outputs\/)[^'"`\n]*)['"`]/g, dir: 'read' }
    ];

    patterns.forEach(function(pattern) {
        var m;
        while ((m = pattern.re.exec(src)) !== null) {
            var file = matchedArtifactFile(m, pattern);
            if (pattern.dir === 'write') add(writes, file);
            else add(reads, file);
        }
    });

    return { reads: unique(reads).sort(), writes: unique(writes).sort() };
}

function renderSideEffect(label, captures) {
    var out = label;
    captures.forEach(function(c, i) {
        // captures start at regex group 2 (group 1 is the quote character)
        out = out.replace(new RegExp('\\$' + (i + 2), 'g'), c);
    });
    return out;
}

function collectSideEffects(src) {
    var effects = [];
    var seen = {};

    var patterns = [
        { re: /jira_move_to_status\s*\(\s*\{[^}]*statusName:\s*(['"`])([^'"`]+)\1/g, label: 'move ticket to status "$2"' },
        { re: /jira_transition_to_status\s*\(\s*\{[^}]*statusName:\s*(['"`])([^'"`]+)\1/g, label: 'transition ticket to status "$2"' },
        { re: /jira_add_label\s*\(\s*\{[^}]*label:\s*(['"`])([^'"`]+)\1/g, label: 'add label "$2"' },
        { re: /jira_remove_label\s*\(\s*\{[^}]*label:\s*(['"`])([^'"`]+)\1/g, label: 'remove label "$2"' },
        { re: /jira_update_field\s*\(\s*\{[^}]*field:\s*(['"`])([^'"`]+)\1/g, label: 'update field "$2"' },
        { re: /jira_post_comment\s*\(/g, label: 'post Jira comment' },
        { re: /jira_create_ticket_with_json\s*\(/g, label: 'create Jira ticket' },
        { re: /jira_create_issue\s*\(/g, label: 'create Jira issue' },
        { re: /jira_link_issues\s*\(/g, label: 'link Jira issues' },
        { re: /jira_assign_ticket_to\s*\(/g, label: 'assign ticket' },
        { re: /jira_attach_file_to_ticket\s*\(/g, label: 'attach file to ticket' },
        // Tracker-agnostic layer (js/common/trackers.js): same side effects,
        // dispatched onto jira_* / ado_* / github_* tools at runtime.
        { re: /tracker\.addLabel\s*\([^,]+,\s*(['"`])([^'"`]+)\1\s*\)/g, label: 'add label "$2" (via tracker)' },
        { re: /tracker\.removeLabel\s*\([^,]+,\s*(['"`])([^'"`]+)\1\s*\)/g, label: 'remove label "$2" (via tracker)' },
        { re: /tracker\.postComment\s*\(/g, label: 'post ticket comment (via tracker)' },
        { re: /tracker\.moveToStatus(?:OrMark)?\s*\(/g, label: 'move ticket to status (via tracker)' },
        { re: /tracker\.assignTo\s*\(/g, label: 'assign ticket (via tracker)' },
        { re: /tracker\.createTicket\s*\(/g, label: 'create ticket (via tracker)' },
        { re: /github_create_pr\s*\(/g, label: 'create GitHub PR' },
        { re: /github_create_pull_request\s*\(/g, label: 'create GitHub PR' },
        { re: /github_merge_pr\s*\(/g, label: 'merge GitHub PR' },
        { re: /github_merge_pull_request\s*\(/g, label: 'merge GitHub PR' },
        { re: /github_post_review_comment\s*\(/g, label: 'post PR review comment' },
        { re: /github_create_review_comment\s*\(/g, label: 'post PR review comment' },
        { re: /github_update_pr\s*\(/g, label: 'update PR' },
        { re: /github_close_pr\s*\(/g, label: 'close PR' },
        { re: /git push/g, label: 'git push' },
        { re: /git checkout/g, label: 'git checkout' },
        { re: /git merge/g, label: 'git merge' },
        { re: /git rebase/g, label: 'git rebase' }
    ];

    patterns.forEach(function(pattern) {
        var match;
        while ((match = pattern.re.exec(src)) !== null) {
            var captures = [];
            for (var i = 2; i < match.length; i++) {
                if (match[i] !== undefined) captures.push(match[i]);
            }
            var label = renderSideEffect(pattern.label, captures);
            if (!seen[label]) {
                seen[label] = true;
                effects.push(label);
            }
        }
    });

    return effects;
}

/**
 * Extract customParams paths used by a JS action source, e.g.
 *   customParams.foo            → foo
 *   customParams['bar']         → bar
 *   customParams.contentOutput.target → contentOutput.target
 */
function collectCustomParamsUsage(src) {
    var found = [];
    var seen = {};
    var patterns = [
        /customParams\.([a-zA-Z_$][\w$]*(?:\.[a-zA-Z_$][\w$]*)*)/g,
        /customParams\[['"]([\w.]+)['"]\]/g
    ];
    patterns.forEach(function(re) {
        var match;
        while ((match = re.exec(src)) !== null) {
            var key = match[1];
            if (!seen[key]) {
                seen[key] = true;
                found.push(key);
            }
        }
    });
    return found.sort();
}

/**
 * Extract local relative require paths from a JS source, e.g.
 *   require('./postTestAutomationResultsHelpers.js') → ./postTestAutomationResultsHelpers.js
 * Built-in (non-relative) requires are ignored — only files next to the
 * action source can carry customParams usage we need to document.
 */
function collectLocalRequires(src) {
    var found = [];
    var re = /require\s*\(\s*['"](\.[^'"]+)['"]\s*\)/g;
    var match;
    while ((match = re.exec(src)) !== null) {
        found.push(match[1]);
    }
    return found;
}

// Resolve a relative require specifier against the requiring file's path,
// without relying on path.dirname/resolve (the unit-test mock only joins).
function resolveLocalRequire(fromFile, reqPath) {
    var base = fromFile.replace(/\\/g, '/');
    var dir = base.substring(0, base.lastIndexOf('/'));
    var parts = (dir + '/' + reqPath).split('/');
    var out = [];
    parts.forEach(function(p) {
        if (p === '.' || p === '') return;
        if (p === '..') { out.pop(); return; }
        out.push(p);
    });
    return out.join('/');
}

/**
 * Extract customParams paths used by a JS action source, e.g.
 *   customParams.foo            → foo
 *   customParams['bar']         → bar
 *   customParams.contentOutput.target → contentOutput.target
 *
 * Local relative requires are followed transitively (with cycle protection):
 * extractions like gh-961 move member accesses into helper modules next to
 * the action, and the generated docs must keep documenting those params.
 *
 * Generic plumbing modules are NOT followed (gh-1346 rework): configLoader /
 * config (the project-config system) and common/trackers (the tracker
 * abstraction) read their own framework-wide override channels
 * (configPath, scmProvider, targetRepository, featureBranchEnabled,
 * branchNamingFnPath, prSearchFnPath, trackerProvider, adoTextFormat,
 * stageFallback, customStatuses, …) from whatever customParams object the
 * action passes through. Following them attributed those channels to every
 * job, so generated docs listed knobs the job never reads — a deployer
 * configuring a JSRunner job from the doc hunted for params that do nothing.
 * Action-specific helper modules (the gh-961 extractions) are still followed.
 */
var PLUMBING_MODULES = {
    'js/configLoader.js': true,
    'js/config.js': true,
    'js/common/trackers.js': true,
    // gh-1416 rework: the generic merge-path module — it reads its own
    // machineAuthor channel from whatever customParams the merge job passes
    // (jobParams.machineAuthor → the per-repo .dmtools/config.js knob),
    // exactly the configLoader/trackers plumbing shape above. Without the
    // pin, the gh-1416 gate wiring (retryMergeGithubPR → mergeVerdictGate →
    // mergeBackstop → reviewPolicy/…) extended the transitive walk into the
    // review-policy chain and the generated retry-merge doc listed five
    // phantom customParams (reviewPolicy, allowApproveWithSuggestions, …)
    // the job never reads — the gh-1346 antipattern, docs-freshness red.
    'js/common/mergeBackstop.js': true
};

// Normalize a resolved require path for the plumbing check: the canonical
// layout prefixes sources with 'agents/', the pack layout does not.
function canonicalModulePath(resolved) {
    return String(resolved || '').replace(/\\/g, '/').replace(/^agents\//, '');
}

function isPlumbingModule(resolved) {
    return !!PLUMBING_MODULES[canonicalModulePath(resolved)];
}

function collectCustomParamsUsageFrom(filePath, src, visited) {
    visited = visited || {};
    if (visited[filePath]) return [];
    visited[filePath] = true;

    var found = [];
    var seen = {};
    function add(key) {
        if (!seen[key]) {
            seen[key] = true;
            found.push(key);
        }
    }

    collectCustomParamsUsage(src).forEach(add);

    collectLocalRequires(src).forEach(function(reqPath) {
        var resolved = resolveLocalRequire(filePath, reqPath);
        if (isPlumbingModule(resolved)) return;
        var helperSrc = readSource(resolved);
        if (!helperSrc) return;
        collectCustomParamsUsageFrom(resolved, helperSrc, visited).forEach(add);
    });

    return found.sort();
}

function analyzeActionFile(filePath, phase) {
    var src = readSource(filePath);
    if (!src) {
        return {
            description: '',
            artifacts: { reads: [], writes: [] },
            effects: [],
            paramsUsed: []
        };
    }

    // gh-1247: extraction tickets move file_write / cli_execute_command
    // literals out of the action into js/common/ helper functions the action
    // delegates to (e.g. branchSetup.writeBranchConflictGuidance). Scan ONLY
    // the bodies of the helper methods the action actually invokes, so the
    // generated docs keep attributing those runtime artifacts to the
    // delegating action without importing every literal in the helper
    // module (over-reporting).
    var srcs = [src];
    collectDelegatedCommonBodies(filePath, src).forEach(function(body) {
        srcs.push(body);
    });

    var artifacts = { reads: [], writes: [] };
    var seenRead = {}, seenWrite = {}, seenEffect = {};
    var effects = [];
    srcs.forEach(function(s) {
        var a = collectArtifacts(s, phase);
        a.reads.forEach(function(p) {
            if (!seenRead[p]) { seenRead[p] = true; artifacts.reads.push(p); }
        });
        a.writes.forEach(function(p) {
            if (!seenWrite[p]) { seenWrite[p] = true; artifacts.writes.push(p); }
        });
        collectSideEffects(s).forEach(function(e) {
            if (!seenEffect[e]) { seenEffect[e] = true; effects.push(e); }
        });
    });
    artifacts.reads.sort();
    artifacts.writes.sort();

    return {
        description: firstJsDescription(src),
        artifacts: artifacts,
        effects: effects,
        paramsUsed: collectCustomParamsUsageFrom(filePath, src)
    };
}

/**
 * Collect the function bodies a source delegates to in js/common/ helpers:
 * resolve `var x = require('./common/...')` bindings, find the member
 * methods the source invokes on each binding (e.g. `bs.writeBranch...`),
 * and extract those methods' bodies from the helper source. Only requires
 * resolving under a `common/` directory are considered; methods not found
 * in the helper are skipped. Extraction is shallow (one level) on purpose.
 */
function collectDelegatedCommonBodies(filePath, src) {
    var bodies = [];
    var seen = {};
    var requireRe = /([A-Za-z_$][\w$]*)\s*=\s*require\s*\(\s*['"](\.[^'"]+)['"]\s*\)/g;
    var req;
    while ((req = requireRe.exec(src)) !== null) {
        var resolved = resolveLocalRequire(filePath, req[2]);
        if (resolved.indexOf('/common/') === -1) continue;
        var helperSrc = readSource(resolved);
        if (!helperSrc) continue;
        var usageRe = new RegExp('\\b' + req[1] + '\\.([A-Za-z_$][\\w$]*)', 'g');
        var usage;
        while ((usage = usageRe.exec(src)) !== null) {
            var name = usage[1];
            if (seen[name + '@' + resolved]) continue;
            seen[name + '@' + resolved] = true;
            var body = extractFunctionBody(helperSrc, name);
            if (body) bodies.push(body);
        }
    }
    return bodies;
}

/**
 * Extract the body of `function name(...) { ... }` (or the
 * `name: function(...) { ... }` object form) from a source. Returns null
 * when the function is not present or has no complete body.
 */
function extractFunctionBody(src, name) {
    var declRe = new RegExp('(?:function\\s+' + name + '|' + name + '\\s*:\\s*function)\\s*\\(');
    var decl = declRe.exec(src);
    if (!decl) return null;
    var start = src.indexOf('{', decl.index);
    if (start === -1) return null;
    var end = findMatchingBrace(src, start);
    return end === -1 ? null : src.substring(start, end + 1);
}

function isQuoteChar(c) {
    return c === "'" || c === '"' || c === '`';
}

// Index of the closing quote for the string whose opening quote is at `i`;
// escaped characters are skipped. Returns src.length - 1 when unterminated.
function skipQuoted(src, i) {
    var quote = src[i];
    for (i = i + 1; i < src.length; i++) {
        if (src[i] === '\\') { i++; continue; }
        if (src[i] === quote) return i;
    }
    return src.length - 1;
}

// Index just past the `}` matching the `{` at `start`, or -1 when the
// source ends before the block closes. Braces inside string literals and
// escaped characters do not affect the depth count.
function findMatchingBrace(src, start) {
    var depth = 0;
    for (var i = start; i < src.length; i++) {
        var c = src[i];
        if (isQuoteChar(c)) { i = skipQuoted(src, i); continue; }
        if (c === '{') { depth++; continue; }
        if (c === '}') {
            depth--;
            if (depth === 0) return i;
        }
    }
    return -1;
}

/**
 * One rendered bullet group ("- Heading:" + indented items) when the list is
 * non-empty; nothing for an empty one.
 */
function pushBulletList(lines, heading, items, formatItem) {
    if (!items || items.length === 0) return;
    lines.push(heading);
    items.forEach(function(item) {
        lines.push('  - ' + formatItem(item));
    });
}

/** True when an action file showed no file I/O, side effects, or customParams usage. */
function hasNoDetectedArtifacts(analysis) {
    return analysis.artifacts.reads.length === 0 &&
        analysis.artifacts.writes.length === 0 &&
        analysis.effects.length === 0 &&
        (!analysis.paramsUsed || analysis.paramsUsed.length === 0);
}

function renderActionSection(label, filePath, phase) {
    if (!filePath) return '';

    var analysis = analyzeActionFile(filePath, phase);
    var lines = [];
    lines.push('### ' + label + ': `' + basename(filePath) + '`');
    lines.push('');
    if (analysis.description) {
        lines.push('_' + escapeMd(analysis.description) + '_');
        lines.push('');
    }
    lines.push('- Source: `' + canonicalRef(filePath) + '`');

    pushBulletList(lines, '- Reads:', analysis.artifacts.reads, function(p) {
        return '`' + p + '`';
    });
    pushBulletList(lines, '- Writes:', analysis.artifacts.writes, function(p) {
        return '`' + p + '`';
    });
    pushBulletList(lines, '- Side effects:', analysis.effects, function(effect) {
        return effect;
    });
    pushBulletList(lines, '- Parameters (customParams):', analysis.paramsUsed, function(p) {
        return '`' + p + '`';
    });

    if (hasNoDetectedArtifacts(analysis)) {
        lines.push('- No detected file I/O or side effects.');
    }

    lines.push('');
    return lines.join('\n');
}

function renderOutputSchemas(outputSchemas) {
    if (!outputSchemas || typeof outputSchemas !== 'object') return '';
    var keys = Object.keys(outputSchemas);
    if (keys.length === 0) return '';
    var out = '### Output schemas\n\n';
    keys.forEach(function(fileName) {
        var schema = outputSchemas[fileName];
        out += '- `' + fileName + '`\n';
        if (schema.required && schema.required.length) {
            out += '  - required: `' + schema.required.join('`, `') + '`\n';
        }
    });
    return out + '\n';
}

function snapshotPath(fileName) {
    var base = fileName.replace(/\.json$/, '.md');
    var p = path.join(SNAPSHOTS_DIR, base);
    try {
        fs.accessSync(resolveReadPath(p), fs.constants.F_OK);
        return canonicalRef(p);
    } catch (e) {
        return null;
    }
}

/**
 * Human-readable doc for an agent. Location by strict naming convention:
 * docs/agents/<configName>.md (configName = JSON file name without .json).
 * metadata.descriptionPath may point to the same file explicitly, but the
 * convention path is always checked as a fallback.
 * Returns { ref, content } or null when no human doc exists.
 */
function humanDocPath(fileName, params) {
    var metadata = (params && params.metadata) || {};
    var base = fileName.replace(/\.json$/, '.md');
    var candidates = [];
    if (metadata.descriptionPath) candidates.push(metadata.descriptionPath);
    candidates.push(path.join(AGENTS_DIR, 'docs', 'agents', base));
    for (var i = 0; i < candidates.length; i++) {
        var p = candidates[i];
        try {
            var content = fs.readFileSync(resolveReadPath(p), 'utf8');
            if (content && content.trim()) {
                return { ref: canonicalRef(path.join(AGENTS_DIR, 'docs', 'agents', base)), content: content };
            }
        } catch (e) {
            // try next candidate
        }
    }
    return null;
}

/** "story_acceptance_criteria.json" → "Story Acceptance Criteria" (page title). */
function agentDisplayName(fileName) {
    return fileName.replace(/\.json$/, '').replace(/_/g, ' ')
        .replace(/\b\w/g, function(c) { return c.toUpperCase(); });
}

/** Every params-derived value the doc renders, with the display defaults applied. */
function resolveAgentIdentity(fileName, config) {
    var params = config.params || {};
    var metadata = params.metadata || {};
    return {
        params: params,
        metadata: metadata,
        customParams: params.customParams || {},
        outputSchemas: params.outputSchemas || null,
        jobClass: config.name || '—',
        contextId: metadata.contextId || '—'
    };
}

/**
 * Embed the human-readable doc from docs/agents/<name>.md (strict naming
 * convention, see humanDocPath) verbatim — minus its own title — so the
 * generated reference stays self-contained and HTML-renderable.
 */
function appendHumanDoc(lines, fileName, params) {
    var human = humanDocPath(fileName, params);
    if (!human) return;
    var humanBody = human.content.trim()
        .replace(/^#\s+.*\n/, '')       // drop the human doc's own title
        .trim();
    lines.push(humanBody);
    lines.push('');
    lines.push('_Human doc: [`' + human.ref + '`](' + human.ref + ')_');
    lines.push('');
}

/** The Attributes table (job class, config, context id, output knobs). */
function appendAttributes(lines, identity, fileName) {
    lines.push('## Attributes');
    lines.push('');
    lines.push('| Attribute | Value |');
    lines.push('|---|---|');
    lines.push('| Job | `' + identity.jobClass + '` |');
    lines.push('| Config | `' + fileName + '` |');
    lines.push('| ContextId | `' + identity.contextId + '` |');
    lines.push('| outputType | `' + (identity.params.outputType || '—') + '` |');
    lines.push('| skipAIProcessing | `' + (identity.params.skipAIProcessing || false) + '` |');
    lines.push('');
}

/**
 * The "Prompt snapshot" section for an existing snapshot file. Returns the
 * snapshot ref (null when none) — the LLM-step section reuses it.
 */
function appendPromptSnapshot(lines, fileName) {
    var snap = snapshotPath(fileName);
    if (!snap) return null;
    lines.push('## Prompt snapshot');
    lines.push('');
    lines.push('Full prompt / instruction set: [`' + snap + '`](' + snap + ')');
    lines.push('');
    return snap;
}

/**
 * Merge customParams declared in the JSON with customParams paths used by
 * the referenced JS actions, so the doc lists every tunable in one place.
 */
function collectJsParamsUsed(params) {
    var jsParamsUsed = [];
    var jsParamsSeen = {};
    [params.preJSAction, params.preCliJSAction, params.postCliJSAction, params.postJSAction, params.timerJSAction]
        .forEach(function(actionPath) {
            if (!actionPath) return;
            analyzeActionFile(actionPath, 'pre').paramsUsed.forEach(function(p) {
                if (!jsParamsSeen[p]) {
                    jsParamsSeen[p] = true;
                    jsParamsUsed.push(p);
                }
            });
        });
    return jsParamsUsed;
}

/** One customParams row: scalars inline, objects/arrays as a fenced json block. */
function appendCustomParam(lines, key, value) {
    if (value !== null && typeof value === 'object') {
        // Objects/arrays as inline code wrap into unreadable blobs —
        // give them a fenced block instead.
        lines.push('- `' + key + '`:\n');
        lines.push('  ```json');
        lines.push('  ' + JSON.stringify(value, null, 2).split('\n').join('\n  '));
        lines.push('  ```');
    } else {
        lines.push('- `' + key + '`: `' + escapeMd(JSON.stringify(value)) + '`');
    }
}

/** The "Custom params" section — omitted entirely when there is nothing to document. */
function appendCustomParams(lines, customParams, jsParamsUsed) {
    if (Object.keys(customParams).length === 0 && jsParamsUsed.length === 0) return;
    lines.push('## Custom params');
    lines.push('');
    Object.keys(customParams).forEach(function(k) {
        appendCustomParam(lines, k, customParams[k]);
    });
    jsParamsUsed.forEach(function(p) {
        // Skip when the JSON already documents the same root key — a
        // duplicate row ("`contentOutput` (used by JS action)" right after
        // "`contentOutput`: {...}") reads as noise.
        var rootKey = p.split('.')[0];
        if (Object.prototype.hasOwnProperty.call(customParams, rootKey)) return;
        lines.push('- `' + p + '` _(used by JS action)_');
    });
    lines.push('');
}

function renderAgentDoc(fileName, config) {
    var identity = resolveAgentIdentity(fileName, config);

    // Humanized config name as the page title: "story_acceptance_criteria" →
    // "Story acceptance criteria". The job class and file name stay in the
    // Attributes table — a title like `Teammate (story_acceptance_criteria.json)`
    // renders as an unreadable headline in HTML.
    var lines = [];
    lines.push('# ' + agentDisplayName(fileName));
    lines.push('');

    appendHumanDoc(lines, fileName, identity.params);

    appendAttributes(lines, identity, fileName);

    var snap = appendPromptSnapshot(lines, fileName);

    lines.push('## Actions');
    lines.push('');
    lines.push(renderActionSection('preJSAction', identity.params.preJSAction, 'pre'));
    lines.push(renderActionSection('preCliJSAction', identity.params.preCliJSAction, 'pre'));
    lines.push(renderActionSection('postCliJSAction', identity.params.postCliJSAction, 'post'));
    lines.push(renderActionSection('postJSAction', identity.params.postJSAction, 'post'));
    lines.push(renderActionSection('timerJSAction', identity.params.timerJSAction, 'post'));

    lines.push('## LLM step');
    lines.push('');
    lines.push('- outputType: `' + (identity.params.outputType || 'none') + '`');
    if (snap) {
        lines.push('- Prompt snapshot: `' + snap + '`');
    }
    lines.push('');

    var schemasMd = renderOutputSchemas(identity.outputSchemas);
    if (schemasMd) {
        lines.push(schemasMd);
    }

    appendCustomParams(lines, identity.customParams, collectJsParamsUsed(identity.params));

    lines.push('---');
    lines.push('_Generated by js/agentDocGenerator.js_');
    return lines.join('\n');
}

function generate() {
    ensureDir(DOCS_DIR);
    var files = listAgentConfigs();
    console.log('Generating docs for', files.length, 'agent(s)');

    files.forEach(function(fileName) {
        var filePath = path.join(AGENTS_DIR, fileName);
        var config = readJson(filePath);
        if (!config) return;

        var doc = renderAgentDoc(fileName, config);
        var outPath = path.join(DOCS_DIR, fileName.replace(/\.json$/, '.md'));
        fs.writeFileSync(outPath, doc);
        console.log('✅', outPath);
    });

    return { success: true, generated: files.length };
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        generate: generate,
        collectArtifacts: collectArtifacts,
        renderAgentDoc: renderAgentDoc,
        renderActionSection: renderActionSection
    };
}

if (require.main === module) {
    generate();
}

